  static Button MakeButton(Control parent,string text,Action action){var button=new Button{Text=text,AutoSize=true,Height=29,MinimumSize=new Size(text.Length<=1?32:58,29)};button.Click+=(s,e)=>action();parent.Controls.Add(button);return button;}
  void WireSurfaceGrid(DataGridView grid,bool obstacleGrid,int column){grid.CurrentCellDirtyStateChanged+=(s,e)=>{if(grid.IsCurrentCellDirty)grid.CommitEdit(DataGridViewDataErrorContexts.Commit);};grid.CellValueChanged+=(s,e)=>{if(refresh||e.RowIndex<0||e.ColumnIndex!=column)return;string id=Convert.ToString(grid.Rows[e.RowIndex].Cells[column].Value);if(TerrainGeometry.Surface(doc,id)==null)return;BeginChange();if(obstacleGrid)doc.Obstacles[e.RowIndex].SurfaceId=id==TerrainGeometry.Ground?null:id;else doc.Points[e.RowIndex].SurfaceId=id==TerrainGeometry.Ground?null:id;EndChange();};}
  void EditInspector(PropertyGrid grid,PropertyValueChangedEventArgs e,bool settings){if(refresh||grid.SelectedObject==null)return;var descriptor=e.ChangedItem.PropertyDescriptor;object target=grid.SelectedObject,now=descriptor.GetValue(target);descriptor.SetValue(target,e.OldValue);BeginChange();descriptor.SetValue(target,now);try{if(settings){var test=new MapDocument{Settings=doc.Settings};if(test.Validate(false).Count>0)throw new Exception(String.Join(" / ",test.Validate(false).Take(4).ToArray()));}else DraftRules.Check(doc);}catch(Exception error){descriptor.SetValue(target,e.OldValue);MessageBox.Show(this,error.Message);}EndChange();}
  void AddTerrain(bool ramp){canvas.CancelInteraction();viewTabs.SelectedIndex=0;terrainTools.ShowSurfaces();terrainTools.AddSurface(ramp);SetMode(4);}
  void SetActiveSurface(string id){canvas.ActiveSurfaceId=TerrainGeometry.Key(id);bool was=refresh;refresh=true;for(int i=0;i<surfacePicker.Items.Count;i++)if(((SurfaceChoice)surfacePicker.Items[i]).Id==canvas.ActiveSurfaceId){surfacePicker.SelectedIndex=i;break;}refresh=was;terrainTools.Select(canvas.ActiveSurfaceId);profileView.SelectedSurface=threeView.SelectedSurface=canvas.ActiveSurfaceId;canvas.Invalidate();profileView.Invalidate();threeView.Invalidate();}
  void SelectPoint(int index){if(index<0||index>=doc.Points.Count)return;canvas.Selected=index;canvas.SelectedObstacle=-1;RevealSurface(doc.Points[index].SurfaceId);SelectRows();RefreshPointInspector();canvas.Invalidate();}
  void RefreshPointInspector(){pointProperties.SelectedObject=canvas.Selected>=0&&canvas.Selected<doc.Points.Count?(canvas.Selected==0?(object)new InitialPointInspector(doc):new PointInspector(doc,canvas.Selected)):null;profileView.SelectedPoint=threeView.SelectedPoint=canvas.Selected;}
  void RefreshLive(){terrainTools.RefreshReading();pointProperties.Refresh();bool was=refresh;refresh=true;for(int i=0;i<doc.Points.Count&&i<points.Rows.Count;i++)points.Rows[i].Cells[2].Value=TerrainGeometry.Height(doc,doc.Points[i]).ToString("0.##");refresh=was;profileView.Invalidate();threeView.Invalidate();}
  void CancelPending(){if(pending!=null){doc=MapDocument.Parse(pending);pending=null;}RefreshAll();}
  void ShowChecks(){canvas.CancelInteraction();RefreshAll();viewTabs.SelectedIndex=4;}
