  public void RenderWorkspaceImage(int view,string path){workspaceRendering=true;doc=TerrainGeometry.Demo();savedJson=doc.Json();canvas.ActiveSurfaceId=doc.Terrain.Surfaces[0].Id;RefreshAll();terrainTools.ShowSurfaces();SelectPoint(1);viewTabs.SelectedIndex=Math.Max(0,Math.Min(2,view));RenderEditorImage(path);}
